sharedContracts.interfaceSketch:
// src/workflow/triage/types.ts — union extended, not replaced
type SizeClass = 'epic' | 'feature' | 'small' | 'trivial' | 'bugfix';

// bugfix is the only category whose route depends on a sub-magnitude
type BugfixMagnitude = 'small' | 'sized'; // 'small' -> skip design; 'sized' -> M/L design path

interface BugfixTriageResult {
  sizeClass: 'bugfix';
  magnitude: BugfixMagnitude;
}

interface TriageRoute {
  startStage: WorkflowName;   // 'issue' for bugfix
  standalone: boolean;
  needsPlan: boolean;         // sized -> true, small -> false
  producesLld: boolean;       // sized -> true, small -> false
}

// classify.ts — pure mapping, bugfix branch reads magnitude
declare function routeForSizeClass(
  sizeClass: SizeClass,
  magnitude?: BugfixMagnitude,
): TriageRoute;

// src/workflow/types.ts — closed union gains one member
type WorkflowName =
  | 'brainstorm' | 'define' | 'design.epic' | 'design.story'
  | 'plan' | 'build' | 'issue';

// the synthesized artifact persisted under the docs/ work-item tree
interface IssueArtifact {
  workflow: 'issue';
  title: string;
  reproduction: string;   // steps / observed vs expected
  rootCause: string;      // the diagnosed cause
  fixIntent: string;      // what the correction will do
  magnitude: BugfixMagnitude;   // carried from sc1 for the router
  parentRef?: WorkItemRef | null;  // stamped from sc3 when located; null = standalone
  approvedAt?: string | null;      // standard approve stamp
}

// WorkItemRef is the existing tracker ref shape (reused, not redefined here)
type WorkItemRef = { epicHash?: string; storyId?: string; slug?: string };

type LocateTier = 'deterministic' | 'graph-ownership' | 'semantic' | 'prompt' | 'standalone';

interface ParentLocation {
  tier: LocateTier;            // which tier decided
  parentRef: WorkItemRef | null;   // null iff tier === 'standalone'
  confidence: number;          // 0..1; auto-attach only above the high threshold
  evidence: string[];          // cited files/entities/artifacts that grounded the match
}

// entry point (implementation reuses tracker/resolve.ts + graph + embeddings)
declare function locateParent(input: {
  touchedPaths: string[];
  defectDescription: string;
}): Promise<ParentLocation>;
